    .clk(clk),
    .rst_n(rst_n),
    .start(start),
    .tx_data(tx_data),
    .miso(miso),
    .rx_data(rx_data),
    .busy(busy),
    .done(done),
    .sclk(sclk),
    .mosi(mosi),
    .cs_n(cs_n)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  always @(negedge sclk or posedge cs_n) begin
    if (cs_n) begin
      miso_bit = 7;
      miso = miso_pattern[7];
    end else if (miso_bit > 0) begin
      miso_bit = miso_bit - 1;
      miso = miso_pattern[miso_bit];
    end
  end

  always @(posedge sclk) begin
    if (!cs_n) begin
      sclk_edge_count = sclk_edge_count + 1;
    end
  end

  initial begin
    rst_n = 1'b0;
    start = 1'b0;
    tx_data = 8'd0;
    miso_pattern = 8'h3C;
    miso_bit = 7;
    sclk_edge_count = 0;
    miso = miso_pattern[7];
