module tb_top;
  reg clk;
  reg rst_n;
  reg [7:0] duty;
  wire pwm_out;
  integer high_count;
  integer i;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .duty(duty),
    .pwm_out(pwm_out)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  initial begin
    rst_n = 1'b0;
    duty = 8'd3;
