module fir_filter_core #(
    parameter WIDTH = 8,
    parameter RESULT_WIDTH = 11
) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    input wire [WIDTH-1:0] sample,
    output reg result_valid,
    output reg [RESULT_WIDTH-1:0] result
);

  reg [WIDTH-1:0] sample_d0;
  reg [WIDTH-1:0] sample_d1;
  wire [RESULT_WIDTH-1:0] stage0;
  wire [RESULT_WIDTH-1:0] stage1;
  wire [RESULT_WIDTH-1:0] filtered_result;

  mac_unit #(
    .WIDTH(WIDTH),
    .ACC_WIDTH(RESULT_WIDTH)
  ) u_mac_new_sample (
    .sample(sample),
    .coefficient(2'd1),
    .accum({RESULT_WIDTH{1'b0}}),
    .result(stage0)
  );

  mac_unit #(
    .WIDTH(WIDTH),
    .ACC_WIDTH(RESULT_WIDTH)
  ) u_mac_previous_sample (
    .sample(sample_d0),
    .coefficient(2'd2),
    .accum(stage0),
    .result(stage1)
  );

  mac_unit #(
    .WIDTH(WIDTH),
    .ACC_WIDTH(RESULT_WIDTH)
  ) u_mac_oldest_sample (
    .sample(sample_d1),
    .coefficient(2'd1),
    .accum(stage1),
    .result(filtered_result)
  );

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      sample_d0 <= {WIDTH{1'b0}};
      sample_d1 <= {WIDTH{1'b0}};
      result_valid <= 1'b0;
      result <= {RESULT_WIDTH{1'b0}};
    end else begin
      result_valid <= sample_valid;
      if (sample_valid) begin
        result <= filtered_result;
        sample_d1 <= sample_d0;
        sample_d0 <= sample;
      end
    end
  end

endmodule

module mac_unit #(
    parameter WIDTH = 8,
    parameter ACC_WIDTH = 11
) (
    input wire [WIDTH-1:0] sample,
    input wire [1:0] coefficient,
    input wire [ACC_WIDTH-1:0] accum,
    output wire [ACC_WIDTH-1:0] result
);

  wire [ACC_WIDTH-1:0] extended_sample;
  wire [ACC_WIDTH-1:0] product_x1;
  wire [ACC_WIDTH-1:0] product_x2;

  assign extended_sample = {{(ACC_WIDTH-WIDTH){1'b0}}, sample};
  assign product_x1 = coefficient[0] ? extended_sample : {ACC_WIDTH{1'b0}};
  assign product_x2 = coefficient[1] ? (extended_sample << 1) : {ACC_WIDTH{1'b0}};
  assign result = accum + product_x1 + product_x2;

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg sample_valid;
  reg [7:0] sample;
  wire result_valid;
  wire [10:0] result;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .sample_valid(sample_valid),
    .sample(sample),
    .result_valid(result_valid),
    .result(result)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task send_and_expect;
    input [7:0] value;
    input [10:0] expected;
    begin
      @(negedge clk);
      sample = value;
      sample_valid = 1'b1;
      @(posedge clk);
      #1;
      if (result_valid !== 1'b1) begin
        $display("TEST_FAIL result_valid was not asserted");
        $finish;
      end
      if (result !== expected) begin
        $display("TEST_FAIL expected result=%0d got %0d", expected, result);
        $finish;
      end
      @(negedge clk);
      sample_valid = 1'b0;
    end
  endtask

  initial begin
    rst_n = 1'b0;
    sample_valid = 1'b0;
    sample = 8'd0;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    send_and_expect(8'd1, 11'd1);
    send_and_expect(8'd2, 11'd4);
    send_and_expect(8'd3, 11'd8);

    @(posedge clk);
    #1;
    if (result_valid !== 1'b0) begin
      $display("TEST_FAIL result_valid did not clear");
      $finish;
    end
    $display("TEST_PASS");
    $finish;
  end
endmodule

